def ways(remaining, base, N):
    p = base ** N
    if p > remaining: return 0          # base too big → dead end
    if p == remaining: return 1         # exact hit → one way
    # include base^N, or skip it — base always advances
    return ways(remaining - p, base + 1, N) + ways(remaining, base + 1, N)

