public int powerSum(int X, int N) {
    java.util.List<Integer> powers = new java.util.ArrayList<>();
    for (int b = 1; Math.pow(b, N) <= X; b++) powers.add((int) Math.pow(b, N));
    int m = powers.size(), count = 0;
    for (int mask = 0; mask < (1 << m); mask++) {
        int sum = 0;
        for (int i = 0; i < m; i++) {
            if ((mask & (1 << i)) != 0) sum += powers.get(i);
        }
        if (sum == X) count++;
    }
    return count;
}

code.python:
def power_sum(X: int, N: int) -> int:
    powers = []
    b = 1
    while b ** N <= X:
        powers.append(b ** N)
        b += 1
    m = len(powers)
    count = 0
    for mask in range(1 << m):
        total = sum(powers[i] for i in range(m) if mask & (1 << i))
        if total == X:
            count += 1
    return count

