private int ways(int remaining, int base, int N) {
    int p = (int) Math.pow(base, N);
    if (p > remaining) return 0;          // overshoot → no larger base helps
    if (p == remaining) return 1;         // exact hit → one representation
    // include base^N, or skip it — base advances either way (uniqueness)
    return ways(remaining - p, base + 1, N) + ways(remaining, base + 1, N);
}

