def power_sum(X: int, N: int) -> int:
    def ways(remaining: int, base: int) -> int:
        p = base ** N
        if p > remaining:
            return 0                      # overshoot → prune
        if p == remaining:
            return 1                      # exact hit → one representation
        # include base^N, or skip it — base advances either way (uniqueness)
        return ways(remaining - p, base + 1) + ways(remaining, base + 1)

    return ways(X, 1)

